import re, pathlib
files = [".env", "config/payment-runtime.env", "config/ir-vault.env"]
targets = ["STRIPE_SECRET_KEY","PAYMENT_WEBHOOK_SECRET","DATABASE_URL","IR_VAULT_TOKEN","AWS_SECRET_ACCESS_KEY"]
