    if not p.exists(): continue
    for line in p.read_text().splitlines():
        line=line.strip()
        if not line or line.startswith("#"): continue
        if "=" not in line: 
            print("  (unparsed)", line); continue
        k,v = line.split("=",1)
        k=k.strip(); v=v.strip().strip('"').strip("'")
        secret = k in targets
        if secret:
            mask = f"{v[:4]}...{v[-2:]}" if len(v)>8 else "***"
            print(f"  {k}: PRESENT len={len(v)} mask={mask}")
        else:
            print(f"  {k}={v}")
        found.setdefault(k, []).append((f, v, secret))
print()
print("=== target coverage ===")
for t in targets + other:
    if t in found:
        for (f,v,secret) in found[t]:
            print(f"{t}: {f} len={len(v)} secret={secret}")
    else:
        print(f"{t}: NOT FOUND in any file")
